float map(vec3 p) {
    float a = iTime+(sin(iTime*.3)*3.);
    p.xy *= mat2(cos(a), -sin(a), sin(a), cos(a));
    p.yz *= mat2(cos(a), -sin(a), sin(a), cos(a));
    p.xz *= mat2(cos(a), sin(a), -sin(a), cos(a));
    vec4 q = vec4(p.x,p.y,p.z,sin(iTime));
    p.xy *= mat2(cos(2.0 + q.z + vec4(0,11,33,0)));
    p.xy *= mat2(cos(q + vec4(0,11,33,0)));
    return max(abs(p).x-.428, max(abs(p).y-.428, abs(p).z-.428));
}

vec3 palette(float t){
    return 0.35 + 0.5*cos(6.2831*(vec3(0.3,0.5,0.7)*t + vec3(0,0.2,0.4) * sin(iTime * .2)));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0,0,-5.0);
    vec3 rd = normalize(vec3(uv, 1.5));
    vec3 col = vec3(0.0);
    float dis;
    float t = 6.0;
    for(float i=0.;i<64.;i++){vec3 p = ro + rd * t; float d = map(p); if(d < 0.001) break; t += d * 0.7; col += palette(t*0.1) / (d+0.5);}

    fragColor = vec4(col/(2.0+col),1.0);
}
